@import url("https://fonts.googleapis.com/css2?family=Barlow+Semi+Condensed:wght@600;700;800&family=Outfit:wght@400;500;600;700;800&display=swap");
.fls-p{--navy:#0A1A33;--navy2:#0E2A4F;--navy3:#133A6B;--blue:#0090D8;--blue2:#38B6EF;--soft:#E8F5FD;--red:#E63312;--red2:#B81F05;--green:#1F9D57;--ink:#15222F;--mut:#5A6E82;--line:#E2E9F1;--bg:#F4F8FC;--gut:20px;
 font-family:Outfit,system-ui,Arial,sans-serif;color:var(--ink);line-height:1.7;font-size:16.5px;-webkit-font-smoothing:antialiased;background:#fff;overflow-x:clip}
.fls-p *,.fls-p *::before,.fls-p *::after{box-sizing:border-box;margin:0;padding:0}
.fls-p svg{width:18px;height:18px;flex-shrink:0}
.fls-p a{color:inherit;text-decoration:none}
.fls-p h1,.fls-p h2,.fls-p h3{font-family:Outfit,system-ui,sans-serif;font-weight:800;color:var(--navy);line-height:1.1;letter-spacing:-.025em}
.fls-p h1{font-size:clamp(2.1rem,4.2vw,3.6rem)}
.fls-p h2{font-size:clamp(1.35rem,2vw,1.7rem)}
.fls-p p{overflow-wrap:anywhere}
.fls-p .wrap{max-width:1400px;margin:0 auto;padding-left:var(--gut);padding-right:var(--gut)}
.fls-p .eyebrow{display:inline-flex;align-items:center;gap:.55rem;font-family:'Barlow Semi Condensed',sans-serif;font-weight:700;font-size:1rem;letter-spacing:.2em;text-transform:uppercase;color:var(--blue);margin-bottom:.6rem}
.fls-p .eyebrow::before{content:"";width:26px;height:3px;border-radius:2px;background:var(--red)}
.fls-p .ilink{color:var(--blue);font-weight:600;border-bottom:1.5px solid rgba(0,144,216,.3);transition:border-color .2s}
.fls-p .ilink:hover{border-color:var(--blue)}

/* buttons */
.fls-p .btn{position:relative;overflow:hidden;isolation:isolate;display:inline-flex;align-items:center;justify-content:center;gap:.6rem;font-family:'Barlow Semi Condensed',sans-serif;font-weight:700;font-size:1.08rem;letter-spacing:.05em;text-transform:uppercase;border:0;border-radius:999px;padding:.95rem 1.7rem;cursor:pointer;transition:background .2s,transform .2s,box-shadow .2s,color .2s,border-color .2s;white-space:nowrap;line-height:1.2}
.fls-p .btn::before{content:"";position:absolute;top:0;left:-140%;width:55%;height:100%;z-index:-1;background:linear-gradient(90deg,transparent,rgba(255,255,255,.38),transparent);transform:skewX(-22deg);transition:left .65s cubic-bezier(.4,0,.2,1)}
.fls-p .btn:hover{transform:translateY(-2px)}
.fls-p .btn:hover::before{left:150%}
.fls-p .btn svg{width:17px;height:17px;transition:transform .28s}
.fls-p .btn:hover svg{transform:translateX(4px)}
.fls-p .btn-red{background:var(--red);color:#fff;box-shadow:0 10px 24px rgba(230,51,18,.3)}
.fls-p .btn-red:hover{background:var(--red2)}
.fls-p .btn-wht{background:rgba(255,255,255,.08);color:#fff;border:2px solid rgba(255,255,255,.34)}
.fls-p .btn-wht:hover{background:#fff;color:var(--navy)}
.fls-p .btn-wht:hover svg{transform:none}
.fls-p .btn-navy{background:var(--navy);color:#fff}
.fls-p .btn-navy:hover{background:var(--navy3)}
.fls-p .btn-line{background:#fff;color:var(--navy);border:2px solid var(--line)}
.fls-p .btn-line:hover{border-color:var(--blue);color:var(--blue)}
.fls-p .btn-line:hover svg{transform:none}

/* ---------- shared hero card ---------- */
.fls-p .p-hero{padding:28px 0 0}
.fls-p .p-hbox{position:relative;border-radius:30px;overflow:hidden;background:linear-gradient(140deg,var(--navy) 0%,#07162B 55%,var(--navy2) 100%);box-shadow:0 30px 70px rgba(10,26,51,.22)}
.fls-p .p-hbox::before{content:"";position:absolute;inset:0;opacity:.07;
 background-image:repeating-linear-gradient(0deg,#fff 0 1.5px,transparent 1.5px 74px),repeating-linear-gradient(90deg,#fff 0 1.5px,transparent 1.5px 74px)}
.fls-p .p-hbox::after{content:"";position:absolute;right:-10%;top:-60%;width:58%;height:220%;background:radial-gradient(circle,rgba(0,144,216,.32),transparent 62%)}
.fls-p .p-hin{position:relative;z-index:2;padding:58px 64px 60px;display:grid;grid-template-columns:minmax(0,1.25fr) minmax(0,.75fr);gap:44px;align-items:center}
.fls-p .p-hin>*{min-width:0}
.fls-p .p-crumb{display:flex;align-items:center;gap:.5rem;flex-wrap:wrap;font-size:.88rem;color:#9FBCD6;margin-bottom:1.3rem}
.fls-p .p-crumb a{color:#C6DCEF;font-weight:600}
.fls-p .p-crumb a:hover{color:#fff}
.fls-p .p-crumb svg{width:13px;height:13px;color:#5E7E9C}
.fls-p .p-crumb span[aria-current]{color:#fff;font-weight:600}
.fls-p .p-hero .eyebrow{color:var(--blue2)}
.fls-p .p-hero h1{color:#fff}
.fls-p .p-hero .sub{font-size:1.1rem;color:#C6DCEF;margin-top:1rem;max-width:36rem}
.fls-p .p-upd{display:inline-flex;align-items:center;gap:.45rem;margin-top:1.4rem;background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.18);padding:.45rem 1rem;border-radius:999px;font-size:.88rem;font-weight:600;color:#fff}
.fls-p .p-upd svg{width:15px;height:15px;color:var(--blue2)}
.fls-p .p-short{background:rgba(255,255,255,.06);border:1px solid rgba(255,255,255,.16);border-radius:20px;padding:24px 24px 20px;backdrop-filter:blur(8px)}
.fls-p .p-short h2{color:#fff;font-size:1.02rem;letter-spacing:.14em;text-transform:uppercase;margin-bottom:.9rem;display:flex;align-items:center;gap:.6rem}
.fls-p .p-short h2::before{content:"";width:22px;height:3px;border-radius:2px;background:var(--red)}
.fls-p .p-short ul{list-style:none;display:grid;gap:.15rem}
.fls-p .p-short li{display:flex;gap:.7rem;align-items:flex-start;padding:.55rem 0;border-bottom:1px solid rgba(255,255,255,.12);color:#E4EEF7;font-size:.97rem;line-height:1.5}
.fls-p .p-short li:last-child{border-bottom:0}
.fls-p .p-short li svg{width:21px;height:21px;color:#fff;background:var(--blue);border-radius:50%;padding:4.5px;margin-top:.05rem}

/* ---------- legal body ---------- */
.fls-p .p-body{padding:70px 0 40px}
.fls-p .p-grid{display:grid;grid-template-columns:290px minmax(0,1fr);gap:56px;align-items:start;max-width:1180px;margin:0 auto}
.fls-p .p-grid>*{min-width:0}
.fls-p .p-toc{position:sticky;top:120px;background:var(--bg);border:1px solid var(--line);border-radius:18px;padding:22px 20px 16px}
.fls-p .p-toc b{display:block;font-family:'Barlow Semi Condensed',sans-serif;font-weight:700;font-size:.92rem;letter-spacing:.16em;text-transform:uppercase;color:var(--mut);margin-bottom:.6rem}
.fls-p .p-toc ol{list-style:none;counter-reset:toc}
.fls-p .p-toc li{counter-increment:toc;border-bottom:1px solid var(--line)}
.fls-p .p-toc li:last-child{border-bottom:0}
.fls-p .p-toc a{display:flex;align-items:center;gap:.7rem;padding:.62rem 0;font-weight:600;font-size:.95rem;color:var(--navy);transition:color .2s}
.fls-p .p-toc a::before{content:"0" counter(toc);font-family:Outfit,sans-serif;font-weight:800;font-size:.8rem;color:var(--blue);background:#fff;border:1px solid var(--line);border-radius:8px;width:30px;height:26px;display:inline-flex;align-items:center;justify-content:center;flex:none;transition:.2s}
.fls-p .p-toc a:hover{color:var(--blue)}
.fls-p .p-toc a:hover::before{background:var(--navy);border-color:var(--navy);color:#fff}
.fls-p .p-intro{font-size:1.1rem;color:var(--ink);line-height:1.75;padding-bottom:1.8rem;margin-bottom:.6rem;border-bottom:1px solid var(--line)}
.fls-p .p-sec{display:grid;grid-template-columns:52px minmax(0,1fr);gap:20px;padding:28px 0;border-bottom:1px solid var(--line);scroll-margin-top:130px;counter-increment:psec}
.fls-p .p-secs{counter-reset:psec}
.fls-p .p-sec:last-child{border-bottom:0}
.fls-p .p-sec .num{width:52px;height:52px;border-radius:14px;background:linear-gradient(145deg,var(--navy),var(--navy3));color:#fff;display:flex;align-items:center;justify-content:center}
.fls-p .p-sec .num svg{width:23px;height:23px;color:var(--blue2)}
.fls-p .p-sec h2{margin:.55rem 0 .55rem}
.fls-p .p-sec p{color:var(--mut);line-height:1.78}
.fls-p .p-sec p+p{margin-top:.8rem}
.fls-p .p-sec p strong{color:var(--navy)}
.fls-p .p-call{display:inline-flex;align-items:center;gap:.5rem;margin-top:1rem;font-family:Outfit,sans-serif;font-weight:800;font-size:1.2rem;color:var(--navy)}
.fls-p .p-call svg{width:20px;height:20px;color:var(--red)}
.fls-p .p-call:hover{color:var(--red)}

/* ---------- help strip ---------- */
.fls-p .p-help{padding:30px 0 90px}
.fls-p .p-helpbox{position:relative;overflow:hidden;max-width:1180px;margin:0 auto;border-radius:24px;background:linear-gradient(118deg,var(--navy3),var(--navy));padding:42px 46px;color:#fff;display:grid;grid-template-columns:minmax(0,1.3fr) auto;gap:30px;align-items:center}
.fls-p .p-helpbox::after{content:"";position:absolute;right:-8%;top:-60%;width:46%;height:220%;background:radial-gradient(circle,rgba(0,144,216,.36),transparent 62%)}
.fls-p .p-helpbox>*{position:relative;z-index:2;min-width:0}
.fls-p .p-helpbox .eyebrow{color:#7FD2F7}
.fls-p .p-helpbox h2{color:#fff;font-size:clamp(1.5rem,2.4vw,2.05rem)}
.fls-p .p-helpbox p{color:#C3D9EC;margin-top:.55rem}
.fls-p .p-helpbox .row{display:flex;gap:.8rem;flex-wrap:wrap;justify-content:flex-end}
.fls-p .p-related{max-width:1180px;margin:22px auto 0;display:flex;flex-wrap:wrap;gap:.6rem;align-items:center;color:var(--mut);font-size:.93rem}
.fls-p .p-related a{display:inline-flex;align-items:center;gap:.4rem;background:var(--bg);border:1px solid var(--line);padding:.45rem .95rem;border-radius:999px;font-weight:600;color:var(--navy);transition:.2s}
.fls-p .p-related a svg{width:14px;height:14px;color:var(--blue)}
.fls-p .p-related a:hover{background:var(--navy);border-color:var(--navy);color:#fff}
.fls-p .p-related a:hover svg{color:var(--blue2)}

/* ---------- thank you ---------- */
.fls-p .t-hero{padding:28px 0 0}
.fls-p .t-box{position:relative;border-radius:30px;overflow:hidden;background:linear-gradient(140deg,var(--navy) 0%,#07162B 55%,var(--navy2) 100%);box-shadow:0 30px 70px rgba(10,26,51,.22);text-align:center}
.fls-p .t-box::before{content:"";position:absolute;inset:0;opacity:.07;
 background-image:repeating-linear-gradient(0deg,#fff 0 1.5px,transparent 1.5px 74px),repeating-linear-gradient(90deg,#fff 0 1.5px,transparent 1.5px 74px)}
.fls-p .t-box::after{content:"";position:absolute;left:50%;top:-40%;width:70%;height:150%;transform:translateX(-50%);background:radial-gradient(circle,rgba(0,144,216,.3),transparent 62%)}
.fls-p .t-in{position:relative;z-index:2;max-width:820px;margin:0 auto;padding:62px 32px 120px}
.fls-p .t-tick{width:96px;height:96px;margin:0 auto 1.6rem;border-radius:50%;background:rgba(31,157,87,.16);display:flex;align-items:center;justify-content:center;position:relative;animation:tPop .6s cubic-bezier(.2,1.4,.4,1) both}
.fls-p .t-tick::before{content:"";position:absolute;inset:-10px;border-radius:50%;border:2px solid rgba(31,157,87,.45);animation:tRing 2.4s ease-out .7s infinite}
.fls-p .t-tick span{width:68px;height:68px;border-radius:50%;background:var(--green);display:flex;align-items:center;justify-content:center;box-shadow:0 12px 30px rgba(31,157,87,.45)}
.fls-p .t-tick svg{width:34px;height:34px;color:#fff}
.fls-p .t-tick svg path{stroke-dasharray:30;stroke-dashoffset:30;animation:tDraw .55s ease-out .45s forwards}
@keyframes tPop{from{transform:scale(.4);opacity:0}to{transform:none;opacity:1}}
@keyframes tDraw{to{stroke-dashoffset:0}}
@keyframes tRing{0%{transform:scale(.9);opacity:.8}80%,100%{transform:scale(1.35);opacity:0}}
.fls-p .t-hero .eyebrow{color:#5FD996;justify-content:center}
.fls-p .t-hero .eyebrow::before{background:var(--green)}
.fls-p .t-hero h1{color:#fff}
.fls-p .t-hero h1 em{font-style:normal;color:var(--blue2);display:block}
.fls-p .t-hero .sub{font-size:1.12rem;color:#C6DCEF;margin:1.1rem auto 1.9rem;max-width:40rem;line-height:1.7}
.fls-p .t-cta{display:flex;gap:.9rem;flex-wrap:wrap;justify-content:center}
.fls-p .t-urgent{display:inline-flex;align-items:center;gap:.5rem;margin-top:1.5rem;color:#9FBCD6;font-size:.92rem}
.fls-p .t-urgent svg{width:16px;height:16px;color:var(--red)}

.fls-p .t-steps{position:relative;z-index:3;margin-top:-76px;padding:0 44px}
.fls-p .t-steps-in{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px;counter-reset:ts}
.fls-p .t-step{background:#fff;border:1px solid var(--line);border-radius:18px;padding:26px 24px 24px;box-shadow:0 22px 50px rgba(10,26,51,.13);min-width:0;counter-increment:ts;position:relative}
.fls-p .t-step .ic{width:54px;height:54px;border-radius:15px;background:var(--soft);color:var(--blue);display:flex;align-items:center;justify-content:center;margin-bottom:1rem}
.fls-p .t-step .ic svg{width:25px;height:25px}
.fls-p .t-step.on .ic{background:var(--green);color:#fff;box-shadow:0 10px 22px rgba(31,157,87,.3)}
.fls-p .t-step::after{content:"0" counter(ts);position:absolute;right:20px;top:18px;font-family:Outfit,sans-serif;font-weight:800;font-size:2.4rem;line-height:1;color:var(--bg)}
.fls-p .t-step h2{font-size:1.18rem;margin-bottom:.35rem}
.fls-p .t-step p{color:var(--mut);font-size:.94rem;line-height:1.6}
.fls-p .t-step .done{display:inline-flex;align-items:center;gap:.35rem;margin-top:.75rem;font-family:'Barlow Semi Condensed',sans-serif;font-weight:700;letter-spacing:.1em;text-transform:uppercase;font-size:.84rem;color:var(--green)}
.fls-p .t-step .done svg{width:14px;height:14px}

.fls-p .t-more{padding:76px 0 90px}
.fls-p .t-head{max-width:44rem;margin:0 auto 2.4rem;text-align:center}
.fls-p .t-head .eyebrow{justify-content:center}
.fls-p .t-head h2{font-size:clamp(1.7rem,2.8vw,2.3rem)}
.fls-p .t-head p{color:var(--mut);margin-top:.5rem}
.fls-p .t-links{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:22px;max-width:1180px;margin:0 auto}
.fls-p .t-link{display:flex;flex-direction:column;background:#fff;border:1px solid var(--line);border-radius:18px;padding:26px 24px 24px;min-width:0;position:relative;overflow:hidden;transition:transform .25s,box-shadow .25s,border-color .25s}
.fls-p .t-link::after{content:"";position:absolute;left:0;bottom:0;height:4px;width:0;background:var(--red);transition:width .35s}
.fls-p .t-link:hover{transform:translateY(-5px);box-shadow:0 24px 48px rgba(10,26,51,.13);border-color:transparent}
.fls-p .t-link:hover::after{width:100%}
.fls-p .t-link .ic{width:56px;height:56px;border-radius:15px;background:var(--soft);color:var(--blue);display:flex;align-items:center;justify-content:center;margin-bottom:1rem;transition:.25s}
.fls-p .t-link .ic svg{width:26px;height:26px}
.fls-p .t-link:hover .ic{background:var(--navy);color:var(--blue2)}
.fls-p .t-link h3{font-size:1.18rem;font-weight:700;margin-bottom:.35rem}
.fls-p .t-link p{color:var(--mut);font-size:.94rem;line-height:1.6;flex:1}
.fls-p .t-link .go{display:inline-flex;align-items:center;gap:.4rem;margin-top:1rem;font-family:'Barlow Semi Condensed',sans-serif;font-weight:700;letter-spacing:.06em;text-transform:uppercase;font-size:.98rem;color:var(--red)}
.fls-p .t-link .go svg{width:15px;height:15px;transition:transform .25s}
.fls-p .t-link:hover .go svg{transform:translateX(5px)}

/* reveal */
.fls-p .rv{animation:flspIn .8s both}
.fls-p .rv2{animation-delay:.12s}.fls-p .rv3{animation-delay:.24s}
@keyframes flspIn{from{opacity:0;transform:translateY(22px)}to{opacity:1;transform:none}}
@media (prefers-reduced-motion:reduce){.fls-p .rv,.fls-p .t-tick,.fls-p .t-tick::before{animation:none}.fls-p .t-tick svg path{animation:none;stroke-dashoffset:0}}
.fls-p a:focus-visible{outline:3px solid var(--blue2);outline-offset:3px}

/* ---------- responsive ---------- */
@media(max-width:1180px){
 .fls-p .p-hin{grid-template-columns:1fr;gap:30px;padding:50px 44px 52px}
 .fls-p .p-helpbox{grid-template-columns:1fr}
 .fls-p .p-helpbox .row{justify-content:flex-start}
}
@media(max-width:960px){
 .fls-p .p-grid{grid-template-columns:1fr;gap:30px}
 .fls-p .p-toc{position:static}
 .fls-p .t-steps-in,.fls-p .t-links{grid-template-columns:1fr}
 .fls-p .t-steps{padding:0 24px;margin-top:-64px}
 .fls-p .t-in{padding:52px 28px 104px}
}
@media(max-width:640px){
 .fls-p{--gut:16px}
 .fls-p .p-hero,.fls-p .t-hero{padding-top:14px}
 .fls-p .p-hbox,.fls-p .t-box{border-radius:20px}
 .fls-p .p-hin{padding:36px 22px 38px}
 .fls-p .p-body{padding:46px 0 24px}
 .fls-p .p-sec{grid-template-columns:1fr;gap:12px;padding:24px 0}
 .fls-p .p-sec h2{margin-top:0}
 .fls-p .p-helpbox{padding:32px 22px;border-radius:20px}
 .fls-p .p-helpbox .row .btn,.fls-p .t-cta .btn{width:100%}
 .fls-p .btn{white-space:normal;text-align:center}
 .fls-p .p-help{padding-bottom:60px}
 .fls-p .t-in{padding:40px 20px 96px}
 .fls-p .t-steps{padding:0 12px;margin-top:-58px}
 .fls-p .t-more{padding:54px 0 60px}
}

